using Point = System.Windows.Point; using MouseEventArgs = System.Windows.Input.MouseEventArgs;
namespace FluentSnap;
public enum CaptureMode { Rectangle, Freeform, Window, Fullscreen }
public enum EditorTool { None, Pen, Highlighter, Crop }
public static class ImageLoader { public static BitmapImage Load(string path){var b=new BitmapImage();b.BeginInit();b.CacheOption=BitmapCacheOption.OnLoad;b.UriSource=new Uri(path);b.EndInit();b.Freeze();return b;} }
public sealed class CaptureOverlay : Window
{
 readonly CaptureMode mode; readonly Canvas surface=new(); readonly List<Point> points=[]; readonly Rectangle preview=new(){Stroke=Brushes.White,StrokeThickness=2,Fill=new SolidColorBrush(Color.FromArgb(35,255,255,255)),Visibility=Visibility.Collapsed}; readonly Rectangle windowPreview=new(){Stroke=new SolidColorBrush(Color.FromRgb(91,95,199)),StrokeThickness=3,Fill=new SolidColorBrush(Color.FromArgb(35,91,95,199)),Visibility=Visibility.Collapsed}; Point start; bool selecting; public BitmapSource? Result {get;private set;}
 public CaptureOverlay(CaptureMode mode){this.mode=mode;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;ShowInTaskbar=false;Topmost=true;Background=new SolidColorBrush(Color.FromArgb(120,0,0,0));var v=CaptureService.VirtualBounds;Left=v.Left;Top=v.Top;Width=v.Width;Height=v.Height;Content=surface;try{surface.Background=new ImageBrush(CaptureService.Capture(CaptureService.VirtualBounds)){Stretch=Stretch.Fill,Opacity=0.72};}catch{surface.Background=new SolidColorBrush(Color.FromArgb(180,20,20,24));}surface.Children.Add(preview);surface.Children.Add(windowPreview);surface.Cursor=Cursors.Cross;surface.MouseLeftButtonDown+=Down;surface.MouseMove+=Move;surface.MouseLeftButtonUp+=Up;KeyDown+=(_,e)=>{if(e.Key==Key.Escape){Close();}};Loaded+=(_,_)=>{Focus();if(mode==CaptureMode.Fullscreen)Dispatcher.BeginInvoke(CaptureFullscreen,DispatcherPriority.ApplicationIdle);};}
 void Down(object _,MouseButtonEventArgs e){if(mode==CaptureMode.Window){FinishWindow();return;}start=e.GetPosition(surface);points.Clear();points.Add(start);selecting=true;surface.CaptureMouse();}
 void Move(object _,MouseEventArgs e){if(mode==CaptureMode.Window){ShowWindowPreview();return;}if(!selecting||e.LeftButton!=MouseButtonState.Pressed)return;var p=e.GetPosition(surface);points.Add(p);if(mode==CaptureMode.Rectangle)ShowRectangle(Rect(start,p));else ShowPolygon();}
 void Up(object _,MouseButtonEventArgs e){if(mode==CaptureMode.Window)return;if(!selecting)return;selecting=false;surface.ReleaseMouseCapture();try{var v=CaptureService.VirtualBounds;if(mode==CaptureMode.Rectangle){var r=Rect(start,e.GetPosition(surface));if(r.Width<3||r.Height<3)return;Result=CaptureAfterClose(()=>CaptureService.Capture(ToPhysical(r,v)));}else {if(points.Count<3)return;Result=CaptureAfterClose(()=>CaptureService.CapturePolygon(points.Select(p=>ToPhysical(p,v)).ToArray()));}}catch(Exception ex){System.Windows.MessageBox.Show(ex.Message,"FluentSnap",MessageBoxButton.OK,MessageBoxImage.Error);Close();}}
 void CaptureFullscreen(){try{Result=CaptureAfterClose(()=>CaptureService.Capture(CaptureService.VirtualBounds));}catch(Exception ex){System.Windows.MessageBox.Show(ex.Message,"FluentSnap");Close();}}
 void FinishWindow(){var r=Native.WindowUnderCursor(new System.Windows.Interop.WindowInteropHelper(this).Handle);if(r is null)return;try{Result=CaptureAfterClose(()=>CaptureService.Capture(r.Value));}catch(Exception ex){System.Windows.MessageBox.Show(ex.Message,"FluentSnap");Close();}}
 T CaptureAfterClose<T>(Func<T> action){Close();Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));return action();}
 void ShowWindowPreview(){var r=Native.WindowUnderCursor(new System.Windows.Interop.WindowInteropHelper(this).Handle);if(r is null){windowPreview.Visibility=Visibility.Collapsed;return;}var v=CaptureService.VirtualBounds;var x=(r.Value.Left-v.Left)*ActualWidth/v.Width;var y=(r.Value.Top-v.Top)*ActualHeight/v.Height;windowPreview.Width=r.Value.Width*ActualWidth/v.Width;windowPreview.Height=r.Value.Height*ActualHeight/v.Height;Canvas.SetLeft(windowPreview,x);Canvas.SetTop(windowPreview,y);windowPreview.Visibility=Visibility.Visible;}
 void ShowRectangle(Rect r){Canvas.SetLeft(preview,r.Left);Canvas.SetTop(preview,r.Top);preview.Width=r.Width;preview.Height=r.Height;preview.Visibility=Visibility.Visible;}
 void ShowPolygon(){var geo=new StreamGeometry();using(var c=geo.Open()){c.BeginFigure(points[0],true,true);c.PolyLineTo(points.Skip(1).ToArray(),true,true);}surface.Children.Remove(preview);surface.Children.Add(new System.Windows.Shapes.Path{Data=geo,Stroke=Brushes.White,StrokeThickness=2,Fill=new SolidColorBrush(Color.FromArgb(35,255,255,255))});}
 System.Drawing.Point ToPhysical(Point p,System.Drawing.Rectangle v)=>new(v.Left+(int)Math.Round(p.X*v.Width/ActualWidth),v.Top+(int)Math.Round(p.Y*v.Height/ActualHeight));
 System.Drawing.Rectangle ToPhysical(Rect r,System.Drawing.Rectangle v){var a=ToPhysical(r.TopLeft,v);var b=ToPhysical(r.BottomRight,v);return System.Drawing.Rectangle.FromLTRB(a.X,a.Y,b.X,b.Y);}
 static Rect Rect(Point a,Point b)=>new(Math.Min(a.X,b.X),Math.Min(a.Y,b.Y),Math.Abs(a.X-b.X),Math.Abs(a.Y-b.Y));
}
